                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.horizontal_sales_categories AS ( with metafields AS ( SELECT upper(trim(sku_group)) as sku_group ,CATEGORY as product_type,product_tags from snitch_db.maplemonk.metafields_data qualify row_number() over (partition by upper(trim(sku_group)) order by product_tags desc) = 1 ), price as ( select distinct LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' in REVERSE(value:sku::STRING))) as sku_group, ifnull(value:compareAtPrice::NUMBER,0)::int as compare_at_price, value:price::NUMBER::int as price from snitch_db.maplemonk.new_meafields_product_products_graph_ql, lateral flatten(input => parse_json(variants)) as value ), final_price1 as ( select sku_group, greatest(compare_at_price,price) AS db_original_price, CASE WHEN compare_at_price != 0 THEN LEAST(compare_at_price,price) ELSE GREATEST(price,compare_at_price) END AS db_slashed_price from price where sku_group not in (\'4MSF0002-01-Shirt\', \'4MSN1147-05-Shirt\', \'4MSN1136-11-Shirt\', \'4MSN1180-01-Shirt\', \'4MSN1025-NVYM-Shirt\', \'4MSN1136-06-Shirt\', \'4MSF0001-Smoke-Grey-Chino\', \'4MSF0002-06-Shirt\', \'4MSF0002-11-Shirt\', \'4MSN0973-01-Shirt\', \'4MST2211-01\', \'4MSN1136-07-Shirt\', \'4MSF0001-Khaki-Chino\', \'4MSN1025-BLKM-Shirt\', \'4MSF0001-Aegean-Blue-Chino\', \'4MSF0002-03-Shirt\', \'4MSN1147-02-Shirt\', \'4MSF0001-Black-Chino\', \'4MSN1147-01-Shirt\', \'4MSN1021-White\', \'4MSF0002-10-Shirt\', \'4MSN1147-06-Shirt\', \'4MSN1021-Black\', \'4MSF0001-Moss-Green-Chino\', \'4MSN0973-03-Shirt\', \'4MSN1021-Navy\', \'4MSN1147-04-Shirt\', \'4MSF0001-Chocolate-Brown-Chino\', \'4MST2211-09\', \'4MSN1147-08-Shirt\', \'4MST2211-10\', \'4MSF0002-02-Shirt\', \'4MSN1136-05-Shirt\', \'4MST2211-04\', \'4MST2211-06\', \'SH0018\', \'4MSN1138-02-Shirt\', \'4MSN1024-REDM-Shirt\', \'4MSN1138-01-Shirt\', \'4MSN1136-04-Shirt\', \'4MSN1136-08-Shirt\', \'4MSN1136-09-Shirt\', \'4MST2211-05\', \'4MST2211-11\', \'4MSN1136-12-Shirt\', \'4MSF0001-Ice-Blue-Chino\', \'4MSN1147-03-Shirt\', \'4MST2211-03\', \'4MST2211-12\', \'4MSN1136-13-Shirt\', \'4MST2211-13\', \'4MSN1021-01\', \'4MSN1024-BLUM-Shirt\', \'4MSF0001-Wine-Chino\', \'4MSN1136-01-Shirt\', \'4MSN1024-YLM-Shirt\', \'4MSF0002-07-Shirt\', \'4MSN1207-WHT-Shirt\', \'4MSN0973-02-Shirt\', \'4MSN1147-07-Shirt\', \'4MSF0002-05-Shirt\', \'4MSF0002-08-Shirt\', \'4MST2211-02\', \'4MSF0001-Leisure-Blue-Chino\', \'4MSF0002-04-Shirt\', \'4MSN1136-10-Shirt\', \'4MSF0001-Dark-Mahogany-Chino\', \'4MSN1025-WHTM-Shirt\', \'4MSF0001-Pastel-Green-Chino\', \'4MST2211-07\', \'4MSN1136-02-Shirt\', \'4MSN1024-GRNM-Shirt\', \'4MST2211-08\', \'4MSF0002-12-Shirt\') ), final_price as ( select sku_group, case when sku_group in (\'4MSS2717-07\',\'4MSS2717-03\',\'4MSN1310-02-SHIRT\') then 1199 else round(db_original_price,0) end as original_price, round(db_slashed_price,0) as current_slashed_price from final_price1 where nullif(sku_group,\'\') is not null ), cost_price as ( select upper(trim(sku)) as sku, cost_price from snitch_db.maplemonk.sku_cost_price ), shopify_sales AS ( SELECT order_timestamp::date AS Date, \'Shopify\' AS type, upper(trim(a.sku_group)) as sku_group, b.product_type as category, b.product_tags as product_tags, c.original_price as price, d.cost_price, case when lower(webshopney) = \'snitch_ios\' and lower(tags) = \'snitch_ios\' then \'App2_IOS\' when lower(webshopney) = \'snitch_ios\' and lower(tags) != \'snitch_ios\' then \'App2_Android\' when lower(webshopney) = \'web\' then \'Web\' else \'App\' end as channel, SUM(NULLIF(gross_sales, 0)) AS gross_sales, SUM(NULLIF(quantity, 0)) AS gross_quantity, SUM( CASE WHEN lower(trim(payment_channel)) = \'cod\' and lower(discount_code) not like \'%snitch_rms%\' THEN (quantity)*(c.original_price) - (gross_sales-100) when lower(discount_code) not like \'%snitch_rms%\' then (quantity)*(c.original_price) - (gross_sales) else ((quantity)*(c.original_price) - coupon_discount - gross_sales) END ) AS discount_amount, SUM(CASE WHEN new_customer_flag != \'Repeated\' THEN gross_sales ELSE 0 END) AS new_customers_revenue, SUM(CASE WHEN new_customer_flag = \'Repeated\' THEN gross_sales ELSE 0 END) AS repeat_customers_revenue, COUNT(DISTINCT CASE WHEN new_customer_flag != \'Repeated\' THEN customer_id ELSE NULL END) AS new_customers FROM snitch_db.maplemonk.fact_items_snitch a LEFT JOIN metafields b ON a.sku_group = b.sku_group LEFT JOIN final_price c ON a.sku_group = c.sku_group left join cost_price d on a.sku = d.sku WHERE LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%influ%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') GROUP BY 1, 2, 3, 4, 5, 6, 7, 8 ), marketplace_data AS ( SELECT a.order_date AS Date, \'Marketplace\' AS type, upper(trim(a.sku_group)) as sku_group, c.product_type as category, c.product_tags as product_tags, b.original_price as price, d.cost_price, marketplace_mapped as channel, SUM(NULLIF(a.selling_price, 0)) AS gross_sales, SUM(NULLIF(a.shipping_quantity, 0)) AS gross_quantity, SUM(NULLIF((b.original_price * a.shipping_quantity) - a.selling_price, 0)) AS discount_amount, SUM(CASE WHEN new_customer_flag != \'Repeated\' THEN selling_price ELSE 0 END) AS new_customers_revenue, SUM(CASE WHEN new_customer_flag = \'Repeated\' THEN selling_price ELSE 0 END) AS repeat_customers_revenue, COUNT(DISTINCT CASE WHEN new_customer_flag != \'Repeated\' THEN customer_id ELSE NULL END) AS new_customers FROM snitch_db.maplemonk.unicommerce_fact_items_snitch a left join final_price b on upper(trim(a.sku_group)) = b.sku_group left join metafields c on a.sku_group = c.sku_group left join cost_price d on a.sku = d.sku where marketplace_mapped IN (\'Myntra\',\'SNAPMINT\',\'CRED\',\'DONOSHOP\',\'FYND\',\'AMAZON\',\'MYNTRA\',\'MENSXP\',\'NYKAA_FASHION\',\'AJIO\',\'FLIPKART\') GROUP BY 1, 2, 3, 4, 5, 6, 7, 8 ), stores_data AS ( SELECT order_date AS Date, \'Store\' AS type, upper(trim(a.sku_group)) as sku_group, b.product_type as category, b.product_tags as product_tags, c.original_price as price, d.cost_price, MARKETPLACE_MAPPED AS channel, SUM(NULLIF(selling_price, 0)) AS gross_sales, SUM(NULLIF(shipping_quantity, 0)) AS gross_quantity, sum(shipping_quantity*c.original_price - selling_price) as discount_amount, SUM(CASE WHEN new_customer_flag != \'Repeated\' THEN selling_price ELSE 0 END) AS new_customers_revenue, SUM(CASE WHEN new_customer_flag = \'Repeated\' THEN selling_price ELSE 0 END) AS repeat_customers_revenue, COUNT(DISTINCT CASE WHEN new_customer_flag != \'Repeated\' THEN phone ELSE NULL END) AS new_customers FROM snitch_db.maplemonk.STORE_fact_items_offline a left join metafields b on a.sku_group = b.sku_group LEFT JOIN final_price c ON a.sku_group = c.sku_group left join cost_price d on a.sku = d.sku where marketplace_mapped not like \'%WH%\' and lower(a.sku_group) not like \'cb%\' GROUP BY 1, 2, 3, 4, 5, 6, 7, 8 ), main_data2 as ( select * from shopify_sales union all select * from marketplace_data union all select * from stores_data ), metafields_data as ( select sku_group, occassion_new, print_design, collar_new, material_new, sleeve_type, fit, color, closure, style from snitch_db.maplemonk.metafields_data ), class as ( select sku_group, sku_class from snitch_db.maplemonk.availability_master_v2 qualify row_number() over (partition by sku_group order by status desc) = 1 ) select a.*, b.occassion_new, b.print_design, b.collar_new, b.material_new, b.sleeve_type, b.fit, b.color, b.closure, b.style, c.sku_class from main_data2 a left join metafields_data b on a.sku_group = b.sku_group left join class c on a.sku_group = c.sku_group ) ; create or replace table snitch_db.maplemonk.l1_category_horizontal_sales as ( with l1_category as ( select distinct sku_group, l1_Category, category from snitch_db.maplemonk.category_journey ) select a.sku_group, a.type, a.date, b.category, a.gross_quantity, a.gross_sales, b.l1_category from snitch_db.maplemonk.horizontal_sales_categories a left join l1_category b on upper(trim(a.sku_group)) = upper(trim(b.sku_group)) ); create or replace table snitch_db.maplemonk.affiliate_sales_cost_source as ( select order_date, partner_af, source_af, sum(cost) as cost, sum(sales) as sales, sum(discount) as discount, (sum(discount)/sum(discount+sales))*100 as discount_percentage from snitch_db.maplemonk.affiliate_snitch group by 1,2,3 );",
